// ==================== Custom task types ====================

abstract class GeneratePackMcmeta : DefaultTask() {
    @get:Input
    abstract val packFormat: Property<Int>
    @get:Input
    abstract val packDescription: Property<String>
    @get:OutputFile
    abstract val outputFile: RegularFileProperty

    @TaskAction
    fun generate() {
        val mcmeta = """
            {
              "pack": {
                "pack_format": ${packFormat.get()},
                "description": "${packDescription.get()}"
              }
            }
        """.trimIndent()
        outputFile.get().asFile.writeText(mcmeta)
    }
}

abstract class GenerateItemAssets : DefaultTask() {
    @get:InputDirectory
    abstract val texturesSourceDir: DirectoryProperty
    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    private fun modelParentFor(baseItemId: String): String {
        val handheldKeywords = listOf("sword", "axe", "pickaxe", "shovel", "hoe", "trident")
        return if (handheldKeywords.any { baseItemId.contains(it) })
            "minecraft:item/handheld" else "minecraft:item/generated"
    }

    @TaskAction
    fun generate() {
        val srcDir = texturesSourceDir.get().asFile
        val assetsOut = outputDir.get().asFile
        val texturesOut = File(assetsOut, "textures/item").apply { mkdirs() }
        val modelsOut = File(assetsOut, "models/item").apply { mkdirs() }
        val itemsOut = File(assetsOut, "items").apply { mkdirs() }

        val baseItemDirs = srcDir.listFiles { f -> f.isDirectory }?.sortedBy { it.name } ?: emptyList()

        if (baseItemDirs.isEmpty()) {
            logger.warn("No base-item subfolders found in $srcDir — expected e.g. item_textures/diamond_sword/*.png")
        }

        baseItemDirs.forEach { baseDir ->
            val baseItemId = baseDir.name
            val parent = modelParentFor(baseItemId)

            val pngFiles = baseDir.listFiles { f -> f.isFile && f.extension.equals("png", ignoreCase = true) }
                ?.sortedBy { it.name } ?: emptyList()

            if (pngFiles.isEmpty()) {
                logger.warn("No PNG textures found in ${baseDir.path}")
                return@forEach
            }

            val cases = StringBuilder()
            pngFiles.forEachIndexed { index, pngFile ->
                val itemName = pngFile.nameWithoutExtension
                pngFile.copyTo(File(texturesOut, pngFile.name), overwrite = true)

                File(modelsOut, "$itemName.json").writeText(
                    """
                        {
                          "parent": "$parent",
                          "textures": {
                            "layer0": "minecraft:item/$itemName"
                          }
                        }
                    """.trimIndent()
                )

                if (index > 0) cases.append(",\n")
                cases.append(
                    """
                        {
                          "when": "$itemName",
                          "model": {
                            "type": "minecraft:model",
                            "model": "minecraft:item/$itemName"
                          }
                        }
                    """.trimIndent()
                )
            }

            File(itemsOut, "$baseItemId.json").writeText(
                """
                    {
                      "model": {
                        "type": "minecraft:select",
                        "property": "minecraft:custom_model_data",
                        "cases": [
                          ${cases.toString().prependIndent("      ").trim()}
                        ],
                        "fallback": {
                          "type": "minecraft:model",
                          "model": "minecraft:item/$baseItemId"
                        }
                      }
                    }
                """.trimIndent()
            )
        }
    }
}

abstract class GenerateChecksum : DefaultTask() {
    @get:InputFile
    abstract val inputFile: RegularFileProperty
    @get:OutputFile
    abstract val checksumFile: RegularFileProperty

    @TaskAction
    fun generate() {
        val bytes = inputFile.get().asFile.readBytes()
        val digest = MessageDigest.getInstance("SHA-1").digest(bytes)
        val hex = digest.joinToString("") { "%02x".format(it) }
        checksumFile.get().asFile.writeText(hex)
        logger.lifecycle("SHA-1 checksum: $hex")
    }
}

abstract class PublishResourcePackToGitHub @Inject constructor(
    private val execOperations: ExecOperations
) : DefaultTask() {
    @get:InputFile
    abstract val packFile: RegularFileProperty
    @get:Internal
    abstract val repoDir: DirectoryProperty
    @get:Input
    abstract val branch: Property<String>

    @TaskAction
    fun publish() {
        val repo = repoDir.get().asFile
        require(repo.exists()) { "GitHub repo clone not found at $repo — clone it first." }

        val destFile = File(repo, packFile.get().asFile.name)
        packFile.get().asFile.copyTo(destFile, overwrite = true)

        fun git(vararg args: String): Int =
            execOperations.exec {
                workingDir = repo
                commandLine(listOf("git") + args)
                isIgnoreExitValue = true
            }.exitValue

        git("add", ".")
        git("commit", "-m", "automatic pack update from gradle") // non-zero if nothing changed — that's fine
        val pushResult = git("push", "origin", branch.get())

        if (pushResult != 0) {
            throw GradleException("git push failed (exit $pushResult) — check auth/credentials for $repo")
        }
        logger.lifecycle("Pushed ${destFile.name} to GitHub (${branch.get()})")
    }
}

abstract class UpdateServerProperties : DefaultTask() {
    @get:Input
    abstract val resourcePackUrl: Property<String>
    @get:Input
    abstract val sha1: Property<String>
    @get:OutputFile
    abstract val serverPropertiesFile: RegularFileProperty

    @TaskAction
    fun update() {
        val file = serverPropertiesFile.get().asFile
        file.parentFile?.mkdirs()

        val lines = if (file.exists()) file.readLines().toMutableList() else mutableListOf()

        fun setOrAppend(key: String, value: String) {
            val newLine = "$key=$value"
            val idx = lines.indexOfFirst { it.trim().startsWith("$key=") }
            if (idx >= 0) lines[idx] = newLine else lines.add(newLine)
        }

        setOrAppend("resource-pack", resourcePackUrl.get())
        setOrAppend("resource-pack-sha1", sha1.get())

        file.writeText(lines.joinToString("\n") + "\n")
        logger.lifecycle("Updated $file with resource-pack + resource-pack-sha1")
    }
}

