val githubRepo = "mcexperiment-resourcepack"
val githubBranch = "master"
val githubRepoLocalPath = "D:/mcexperiment-resourcepack"
val rawResourcePackUrl =
    "https://raw.githubusercontent.com/$githubUsername/$githubRepo/$githubBranch/$resourcePackName.zip"

// ==================== Task wiring ====================

val generatePackMcmeta by tasks.registering(GeneratePackMcmeta::class) {
    packFormat.set(46) // 1.21.4+; adjust for your target version
    packDescription.set("Custom textures for the mcexperiment server")
    outputFile.set(packStageDir.map { it.file("pack.mcmeta") })
}

val generateItemAssets by tasks.registering(GenerateItemAssets::class) {
    texturesSourceDir.set(layout.projectDirectory.dir("src/main/resources/item_textures"))
    outputDir.set(packStageDir.map { it.dir("assets/minecraft") })
}

val stageResourcePack by tasks.registering {
    dependsOn(generatePackMcmeta, generateItemAssets)
}

val generateResourcePack by tasks.registering(Zip::class) {
    dependsOn(stageResourcePack)
    from(packStageDir)
    archiveFileName.set("$resourcePackName.zip")
    destinationDirectory.set(packOutputDir)
}

val generateChecksum by tasks.registering(GenerateChecksum::class) {
    inputFile.set(generateResourcePack.flatMap { it.archiveFile })
    checksumFile.set(packOutputDir.map { it.file("$resourcePackName.zip.sha1") })
}

val publishResourcePackToGitHub by tasks.registering(PublishResourcePackToGitHub::class) {
    packFile.set(generateResourcePack.flatMap { it.archiveFile })
    repoDir.set(layout.dir(providers.provider { File(githubRepoLocalPath) }))
    branch.set(githubBranch)
}

val updateServerProperties by tasks.registering(UpdateServerProperties::class) {
    dependsOn(publishResourcePackToGitHub)
    resourcePackUrl.set(rawResourcePackUrl)
    sha1.set(generateChecksum.flatMap { it.checksumFile }.map { it.asFile.readText().trim() })
    serverPropertiesFile.set(serverDir.file("server.properties"))
}

val copyResourcePackToServer by tasks.registering(Copy::class) {
    dependsOn(updateServerProperties)
    from(generateResourcePack.flatMap { it.archiveFile })
    into(serverDir.dir("resourcepacks"))
    doLast { logger.lifecycle("Copied resource pack to: $destinationDir") }
}

tasks.named("assemble") {
    dependsOn(copyResourcePackToServer)
}

tasks.register<Copy>("copyJar") {
    dependsOn(tasks.shadowJar)
    from(tasks.shadowJar.get().archiveFile)
    into(layout.buildDirectory.dir("../server/plugins"))
}

tasks.build {
